CREATE OR REPLACE FUNCTION calculate_sri(scan_resolmm numeric, point_dense integer)
RETURNS numeric AS $$
BEGIN
    -- Handle NULL or non-positive inputs
    IF scan_resolmm IS NULL OR scan_resolmm <= 0 THEN
        RETURN NULL;
    END IF;

    IF point_dense IS NULL OR point_dense <= 0 THEN
        RETURN NULL;
    END IF;

    -- Calculate SRI: (LOG10(scan_resolution_mm * 1000) / LOG10(point_density)) * 5
    RETURN (LOG(scan_resolmm * 1000) / LOG(point_dense)) * 5;
END;
$$ LANGUAGE plpgsql;

