CREATE OR REPLACE FUNCTION calculate_sri(scan_resolmm numeric, point_dense integer)
RETURNS numeric AS $$
BEGIN
    IF scan_resolmm IS NULL OR point_dense IS NULL THEN
        RETURN NULL;
    END IF;

    RETURN (LOG10(scan_resolmm * 1000) / NULLIF(LOG10(point_dense::numeric), 0)) * 5;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION sri_quality_category(sri numeric)
RETURNS text AS $$
BEGIN
    IF sri IS NULL THEN
        RETURN 'Unknown';
    ELSIF sri < 2.0 THEN
        RETURN 'Excellent';
    ELSIF sri < 3.0 THEN
        RETURN 'Good';
    ELSIF sri < 4.0 THEN
        RETURN 'Fair';
    ELSE
        RETURN 'Poor';
    END IF;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

